 function destination(index){let i=dockIds.indexOf(index);if(i>=0)return {y:dockY[i],x:vehicleX[i],dock:i};i=reserveIds.indexOf(index);if(i>=0)return {y:reserveY,x:i?106:-106,reserve:i};return Number.isInteger(index)&&index>=1&&index<=6?{y:slots[index-1],x:0,bay:index-1}:null;}
 function target(s){let best=null,distance=Infinity;for(const id of [...dockIds,...reserveIds,1,2,3,4,5,6]){const d=destination(id),dx=d.bay!==undefined?Math.min(Math.abs(s.cameraX),Math.abs(s.cameraX-37.5),Math.abs(s.cameraX+37.5)):Math.abs(s.cameraX-d.x),dist=Math.hypot(s.camera-d.y,dx);if(dist<distance){distance=dist;best={...d,index:d.dock??d.reserve??d.bay,type:d.dock!==undefined?'dock':d.reserve!==undefined?'reserve':'slot',id};}}return distance<2?best:null;}
