  if(!s.held){const list=t.type==='dock'?s.trucks:t.type==='reserve'?s.reserves:null;if(!list?.[t.index])return {ok:false,message:'请选择有货的车辆'};if(!hasLanding(s,list[t.index],t.type==='reserve'?t.index:-1))return {ok:false,message:'没有可用落位，请换货、切批或结束'};s.held=list[t.index];s.heldSource={id:t.id,type:t.type,index:t.index,column:s.column,batch:s.batchIndex,boxId:s.held.id};list[t.index]=null;s.picks++;s.metrics.columns[s.column].picks++;if(t.type==='reserve')s.metrics.columns[s.column].bufferPicks++;record(s,'pickup',{box:s.held.id,source:t.type});return {ok:true,picked:true,box:{...s.held}};}
